window.OWN_BUNDLES=window.OWN_BUNDLES||{};window.OWN_BUNDLES["revolut"]={html:"<div class=\"own-revolut\">\n  <header class=\"rv-nav\" id=\"rvTop\">\n    <a class=\"rv-brand\" href=\"#rv-top\" aria-label=\"Northwind home\">\n      <span class=\"rv-mark\" aria-hidden=\"true\"></span>\n      <span>Northwind</span>\n    </a>\n    <nav class=\"rv-menu\" aria-label=\"Primary\">\n      <a href=\"#rv-personal\">Operations</a>\n      <a href=\"#rv-business\">Analytics</a>\n      <a href=\"#rv-company\">Company</a>\n    </nav>\n    <div class=\"rv-nav-right\">\n      <button class=\"rv-icon\" type=\"button\" aria-label=\"Language\"><svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><circle cx=\"12\" cy=\"12\" r=\"8.5\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\"/><path d=\"M3.5 12h17M12 3.5c2.6 3 2.6 14 0 17\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\"/></svg></button>\n      <a class=\"rv-link\" href=\"#\">Log in</a>\n      <a class=\"rv-btn rv-btn-primary\" href=\"#rv-plan\">Get started</a>\n      <button class=\"rv-burger\" type=\"button\" aria-label=\"Menu\" data-rv-burger><span></span><span></span><span></span></button>\n    </div>\n  </header>\n\n  <main id=\"rv-top\">\n    <section class=\"rv-hero\" aria-labelledby=\"rv-h1\">\n      <div class=\"rv-hero-glow\" aria-hidden=\"true\"></div>\n      <div class=\"rv-hero-inner\">\n        <h1 id=\"rv-h1\" class=\"rv-h1\">Operations<br>&amp; beyond</h1>\n        <p class=\"rv-hero-sub\">Join the teams running every region, line, and hub on one operating picture.</p>\n        <div class=\"rv-hero-cta\">\n          <a class=\"rv-btn rv-btn-primary rv-btn-lg\" href=\"#rv-plan\">Choose your plan</a>\n          <a class=\"rv-btn rv-btn-outline-dark rv-btn-lg\" href=\"#rv-mockups\">See the product</a>\n        </div>\n        <div class=\"rv-hero-mock\" aria-hidden=\"true\">\n          <div class=\"rv-phone\">\n            <div class=\"rv-phone-notch\"></div>\n            <div class=\"rv-phone-screen\">\n              <p class=\"rv-phone-cap\">This quarter</p>\n              <p class=\"rv-phone-big\">+18.4%</p>\n              <p class=\"rv-phone-sub\">Throughput vs last</p>\n              <svg class=\"rv-phone-chart\" viewBox=\"0 0 240 80\" preserveAspectRatio=\"none\"><path d=\"M2 66 C 40 62, 60 34, 96 40 C 132 46, 150 14, 190 20 C 214 24, 228 8, 238 6\" fill=\"none\" stroke=\"#ffed00\" stroke-width=\"3\" stroke-linecap=\"round\"/></svg>\n              <div class=\"rv-phone-tags\"><span style=\"--c:var(--accent-teal)\">Yield</span><span style=\"--c:var(--accent-light-blue)\">Cost</span><span style=\"--c:var(--accent-pink)\">Alerts</span></div>\n            </div>\n          </div>\n          <div class=\"rv-card-mock\">\n            <span class=\"rv-card-chip\" aria-hidden=\"true\"></span>\n            <p class=\"rv-card-num\">&#8226;&#8226;&#8226;&#8226; 4021</p>\n            <p class=\"rv-card-name\">NORTHWIND OPERATIONS</p>\n          </div>\n        </div>\n      </div>\n    </section>\n\n    <section class=\"rv-subnav\" aria-label=\"Quick links\">\n      <a class=\"rv-pill\" href=\"#rv-personal\">Operations</a>\n      <a class=\"rv-pill\" href=\"#rv-business\">Business</a>\n      <a class=\"rv-pill\" href=\"#rv-mockups\">Premium</a>\n      <a class=\"rv-pill\" href=\"#rv-plan\">Plans</a>\n    </section>\n\n    <section id=\"rv-mockups\" class=\"rv-band rv-band-light\" aria-labelledby=\"rv-mockups-h\">\n      <div class=\"rv-band-inner\">\n        <h2 id=\"rv-mockups-h\" class=\"rv-h2 rv-h2-dark\">The asset is the section</h2>\n        <p class=\"rv-band-sub\">Phone, card, and terminal mockups carry their own depth. No chrome, no caption overlay.</p>\n        <div class=\"rv-mock-grid\">\n          <div class=\"rv-mock rv-mock-phone\">\n            <div class=\"rv-mock-screen\">\n              <span class=\"rv-mock-bar\" style=\"--c:var(--accent-teal)\"></span>\n              <span class=\"rv-mock-bar\" style=\"--c:var(--accent-light-blue)\"></span>\n              <span class=\"rv-mock-bar\" style=\"--c:var(--accent-pink)\"></span>\n            </div>\n          </div>\n          <div class=\"rv-mock rv-mock-card\">\n            <p class=\"rv-mock-tag\">Cost attribution</p>\n            <p class=\"rv-mock-big\">$8.9M</p>\n            <p class=\"rv-mock-small\">saved this year</p>\n          </div>\n          <div class=\"rv-mock rv-mock-terminal\">\n            <p class=\"rv-mock-term-line\"><span style=\"--c:var(--accent-light-green)\">&#10003;</span> Line 4 synced</p>\n            <p class=\"rv-mock-term-line\"><span style=\"--c:var(--accent-warning)\">&#9888;</span> Drift on line 7</p>\n            <p class=\"rv-mock-term-line\"><span style=\"--c:var(--accent-teal)\">&#10003;</span> Forecast in range</p>\n          </div>\n        </div>\n      </div>\n    </section>\n\n    <section id=\"rv-business\" class=\"rv-band rv-band-dark\" aria-labelledby=\"rv-business-h\">\n      <div class=\"rv-band-inner\">\n        <h2 id=\"rv-business-h\" class=\"rv-h2\">Built for the whole operation</h2>\n        <div class=\"rv-feature-grid\">\n          <article class=\"rv-fcard-dark\">\n            <span class=\"rv-fcard-dot\" style=\"--c:var(--accent-teal)\"></span>\n            <h3 class=\"rv-h3\">Live throughput</h3>\n            <p class=\"rv-fcard-copy\">Every line reports the moment it runs. No stale export, no morning reconciliation.</p>\n          </article>\n          <article class=\"rv-fcard-dark\">\n            <span class=\"rv-fcard-dot\" style=\"--c:var(--accent-light-blue)\"></span>\n            <h3 class=\"rv-h3\">Cost attribution</h3>\n            <p class=\"rv-fcard-copy\">Trace cost to the line, shift, and order. Variance bands show where it moved.</p>\n          </article>\n          <article class=\"rv-fcard-dark\">\n            <span class=\"rv-fcard-dot\" style=\"--c:var(--accent-pink)\"></span>\n            <h3 class=\"rv-h3\">Predictive upkeep</h3>\n            <p class=\"rv-fcard-copy\">Drift flags arrive with the exact comparison behind them, before a shift is lost.</p>\n          </article>\n        </div>\n      </div>\n    </section>\n\n    <section id=\"rv-plan\" class=\"rv-band rv-band-dark rv-plan\" aria-labelledby=\"rv-plan-h\">\n      <div class=\"rv-band-inner\">\n        <h2 id=\"rv-plan-h\" class=\"rv-h2\">Pricing that scales with you</h2>\n        <p class=\"rv-band-sub\">Start on a free plan. Move to a subscription when the floor depends on the number.</p>\n        <div class=\"rv-plan-grid\">\n          <article class=\"rv-plan-card\">\n            <span class=\"rv-badge\">Free</span>\n            <h3 class=\"rv-plan-name\">Standard</h3>\n            <p class=\"rv-plan-price\">$0<span>/mo</span></p>\n            <ul class=\"rv-checks\"><li>3 boards</li><li>1 source</li><li>30-day history</li></ul>\n            <a class=\"rv-btn rv-btn-outline-dark rv-btn-block\" href=\"#\">Get started</a>\n          </article>\n          <article class=\"rv-plan-card\">\n            <span class=\"rv-badge\">Popular</span>\n            <h3 class=\"rv-plan-name\">Plus</h3>\n            <p class=\"rv-plan-price\">$12<span>/mo</span></p>\n            <ul class=\"rv-checks\"><li>Unlimited boards</li><li>5 sources</li><li>Alerting</li></ul>\n            <a class=\"rv-btn rv-btn-outline-dark rv-btn-block\" href=\"#\">Choose Plus</a>\n          </article>\n          <article class=\"rv-plan-card rv-plan-featured\">\n            <span class=\"rv-badge rv-badge-feature\">Best value</span>\n            <h3 class=\"rv-plan-name\">Premium</h3>\n            <p class=\"rv-plan-price\">$28<span>/mo</span></p>\n            <ul class=\"rv-checks\"><li>Everything in Plus</li><li>Unlimited sources</li><li>Predictive upkeep</li></ul>\n            <a class=\"rv-btn rv-btn-primary rv-btn-block\" href=\"#\">Choose Premium</a>\n          </article>\n          <article class=\"rv-plan-card\">\n            <span class=\"rv-badge\">Teams</span>\n            <h3 class=\"rv-plan-name\">Metal</h3>\n            <p class=\"rv-plan-price\">$49<span>/seat</span></p>\n            <ul class=\"rv-checks\"><li>Team spaces</li><li>SSO &amp; audit</li><li>Priority support</li></ul>\n            <a class=\"rv-btn rv-btn-outline-dark rv-btn-block\" href=\"#\">Contact sales</a>\n          </article>\n        </div>\n      </div>\n    </section>\n\n    <section id=\"rv-personal\" class=\"rv-band rv-band-light\" aria-labelledby=\"rv-personal-h\">\n      <div class=\"rv-band-inner\">\n        <h2 id=\"rv-personal-h\" class=\"rv-h2 rv-h2-dark\">Frequently asked</h2>\n        <div class=\"rv-faq\">\n          <details class=\"rv-faq-item\" open>\n            <summary>Can I connect my existing historians?</summary>\n            <p>Yes. Northwind reads from spreadsheets, historians, and APIs, and reconciles them into one model.</p>\n          </details>\n          <details class=\"rv-faq-item\">\n            <summary>How fresh is the data?</summary>\n            <p>Streams refresh as sources report &#8212; typically within seconds. Boards never show a batch lag.</p>\n          </details>\n          <details class=\"rv-faq-item\">\n            <summary>Do you offer a free plan?</summary>\n            <p>The Standard plan is free forever for up to three boards and one connected source.</p>\n          </details>\n        </div>\n      </div>\n    </section>\n  </main>\n\n  <footer id=\"rv-company\" class=\"rv-foot\">\n    <div class=\"rv-foot-inner\">\n      <div class=\"rv-foot-brand\">\n        <span class=\"rv-mark rv-mark-light\" aria-hidden=\"true\"></span>\n        <span>Northwind</span>\n      </div>\n      <div class=\"rv-foot-cols\">\n        <h3>Operations</h3><a href=\"#\">Boards</a><a href=\"#\">Alerts</a><a href=\"#\">Regions</a><a href=\"#\">Forecast</a>\n      </div>\n      <div class=\"rv-foot-cols\">\n        <h3>Business</h3><a href=\"#\">Pricing</a><a href=\"#\">Enterprise</a><a href=\"#\">Customers</a><a href=\"#\">Contact</a>\n      </div>\n      <div class=\"rv-foot-cols\">\n        <h3>Company</h3><a href=\"#\">About</a><a href=\"#\">Careers</a><a href=\"#\">Press</a><a href=\"#\">Legal</a>\n      </div>\n    </div>\n    <div class=\"rv-foot-legal\">\n      <span>&copy; 2026 Northwind Analytics</span>\n      <span>Sample data &#8212; showcase only &#183; Terms &#183; Privacy</span>\n    </div>\n  </footer>\n</div>\n",css:"/* ══ NORTHWIND — in the Revolut design language, for showcase.html ═══════════\n   High-contrast two-mode canvas (near-black storytelling / white catalogue)\n   switched in full-bleed bands, Aeonik Pro-style display at 500 with tight\n   line-height and negative tracking, white pill CTAs, a wide accent palette\n   reserved for product mockups, cobalt violet for one featured plan card. */\n\n.own-revolut {\n  --primary: #494fdf;\n  --primary-bright: #4f55f1;\n  --primary-deep: #3a40c4;\n  --on-primary: #ffffff;\n  --ink: #191c1f;\n  --body: #1f2226;\n  --charcoal: #3a3d40;\n  --mute: #505a63;\n  --ash: #5c5e60;\n  --stone: #8d969e;\n  --faint: #c9c9cd;\n  --on-dark: #ffffff;\n  --on-dark-mute: rgba(255, 255, 255, .72);\n  --canvas-light: #ffffff;\n  --canvas-dark: #000000;\n  --surface-soft: #f4f4f4;\n  --surface-card: #ffffff;\n  --surface-deep: #0a0a0a;\n  --surface-elevated: #16181a;\n  --hairline-light: #e2e2e7;\n  --hairline-dark: rgba(255, 255, 255, .12);\n  --hairline-strong: #191c1f;\n  --divider-soft: rgba(255, 255, 255, .06);\n  --accent-teal: #00a87e;\n  --accent-blue-link: #376cd5;\n  --accent-light-blue: #007bc2;\n  --accent-light-green: #428619;\n  --accent-yellow: #b09000;\n  --accent-warning: #ec7e00;\n  --accent-pink: #e61e49;\n  --accent-brown: #936d62;\n  --link: #376cd5;\n\n  --r-sm: 8px;\n  --r-md: 12px;\n  --r-lg: 20px;\n  --r-xl: 28px;\n  --r-full: 9999px;\n\n  --display: 'Aeonik Pro', 'Inter Display', 'General Sans', 'Sohne', system-ui, -apple-system, sans-serif;\n  --ui: 'Inter', system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;\n  --gut: clamp(20px, 4.5cqi, 64px);\n  --section: 88px;\n\n  position: relative;\n  background: var(--canvas-dark);\n  color: var(--on-dark);\n  font-family: var(--ui);\n  font-size: 16px;\n  line-height: 1.5;\n  text-align: left;\n  border-radius: 13px;\n  overflow-x: clip;\n  -webkit-font-smoothing: antialiased;\n}\n.own-revolut *, .own-revolut *::before, .own-revolut *::after { box-sizing: border-box; }\n.own-revolut a { color: inherit; text-decoration: none; }\n.own-revolut button { font: inherit; cursor: pointer; }\n.own-revolut :focus-visible { outline: 2px solid var(--on-dark); outline-offset: 2px; border-radius: var(--r-sm); }\n\n/* ── nav (always dark) ──────────────────────────────────────────────────────── */\n.own-revolut .rv-nav {\n  position: sticky; top: 68px; z-index: 30;\n  display: flex; align-items: center; gap: 22px;\n  height: 64px; padding: 0 var(--gut);\n  background: rgba(0, 0, 0, .82); backdrop-filter: blur(12px);\n  border-bottom: 1px solid var(--hairline-dark);\n}\n.own-revolut .rv-brand { display: inline-flex; align-items: center; gap: 9px; color: var(--on-dark); font-family: var(--display); font-size: 19px; font-weight: 500; letter-spacing: -.3px; }\n.own-revolut .rv-mark { width: 22px; height: 22px; border-radius: var(--r-sm); background: linear-gradient(135deg, var(--primary-bright), var(--primary-deep)); }\n.own-revolut .rv-mark-light { background: linear-gradient(135deg, var(--primary-bright), var(--primary-deep)); }\n.own-revolut .rv-menu { display: flex; align-items: center; gap: 26px; margin: 0 auto; }\n.own-revolut .rv-menu a { font-size: 16px; font-weight: 600; letter-spacing: .24px; color: var(--on-dark); opacity: .86; }\n.own-revolut .rv-menu a:hover { opacity: 1; }\n.own-revolut .rv-nav-right { display: flex; align-items: center; gap: 12px; margin-left: auto; }\n.own-revolut .rv-icon { display: grid; place-items: center; width: 38px; height: 38px; border: 1px solid var(--hairline-dark); border-radius: var(--r-full); background: transparent; color: var(--on-dark); }\n.own-revolut .rv-icon svg { width: 18px; height: 18px; }\n.own-revolut .rv-link { font-size: 16px; font-weight: 600; letter-spacing: .24px; color: var(--on-dark); }\n.own-revolut .rv-link:hover { opacity: .8; }\n.own-revolut .rv-burger { display: none; flex-direction: column; gap: 5px; width: 38px; height: 38px; align-items: center; justify-content: center; border: 1px solid var(--hairline-dark); border-radius: var(--r-full); background: transparent; }\n.own-revolut .rv-burger span { display: block; width: 15px; height: 1.8px; background: var(--on-dark); border-radius: 2px; }\n\n/* ── buttons (all pill-shaped) ───────────────────────────────────────────────── */\n.own-revolut .rv-btn { display: inline-flex; align-items: center; justify-content: center; gap: 8px; height: 48px; padding: 0 28px; border: 1px solid transparent; border-radius: var(--r-full); font-size: 16px; font-weight: 600; letter-spacing: .24px; line-height: 1.5; transition: background-color .2s, opacity .2s; }\n.own-revolut .rv-btn-primary { background: var(--canvas-light); color: var(--canvas-dark); }\n.own-revolut .rv-btn-primary:hover { background: var(--faint); }\n.own-revolut .rv-btn-dark { background: var(--canvas-dark); color: var(--on-dark); }\n.own-revolut .rv-btn-outline-dark { background: var(--canvas-dark); color: var(--on-dark); border-color: var(--on-dark); }\n.own-revolut .rv-btn-outline-dark:hover { background: #1a1a1a; }\n.own-revolut .rv-btn-lg { height: 56px; padding: 0 32px; font-size: 18px; }\n.own-revolut .rv-btn-block { width: 100%; }\n\n/* ── hero (photo-led dark band) ─────────────────────────────────────────────── */\n.own-revolut .rv-hero { position: relative; overflow: hidden; background: var(--canvas-dark); padding: var(--section) var(--gut) 0; }\n.own-revolut .rv-hero-glow { position: absolute; inset: -20% auto auto -5%; width: 60%; height: 130%; background: radial-gradient(50% 50% at 40% 40%, rgba(73, 79, 223, .35), transparent 70%), radial-gradient(40% 40% at 70% 65%, rgba(0, 168, 126, .22), transparent 72%); pointer-events: none; }\n.own-revolut .rv-hero-inner { position: relative; max-width: 1200px; margin: 0 auto; }\n.own-revolut .rv-h1 { font-family: var(--display); font-size: clamp(56px, 9.4cqi, 136px); font-weight: 500; line-height: 1; letter-spacing: -2.72px; color: var(--on-dark); }\n.own-revolut .rv-hero-sub { margin-top: 22px; max-width: 48ch; font-size: 18px; line-height: 1.56; letter-spacing: -.09px; color: var(--on-dark-mute); }\n.own-revolut .rv-hero-cta { display: flex; gap: 12px; margin-top: 30px; flex-wrap: wrap; }\n\n/* ── hero mockups (phone + card) ────────────────────────────────────────────── */\n.own-revolut .rv-hero-mock { position: relative; margin-top: 56px; display: flex; align-items: flex-end; justify-content: center; gap: 32px; flex-wrap: wrap; }\n.own-revolut .rv-phone { position: relative; width: 250px; height: 500px; border-radius: var(--r-xl); background: var(--surface-elevated); border: 1px solid var(--hairline-dark); padding: 14px; box-shadow: 0 50px 100px -60px rgba(73, 79, 223, .8); }\n.own-revolut .rv-phone-notch { width: 70px; height: 6px; border-radius: var(--r-full); background: var(--hairline-dark); margin: 0 auto 16px; }\n.own-revolut .rv-phone-screen { display: grid; gap: 6px; }\n.own-revolut .rv-phone-cap { font-size: 13px; color: var(--stone); }\n.own-revolut .rv-phone-big { font-family: var(--display); font-size: 40px; font-weight: 500; line-height: 1.2; letter-spacing: -.4px; color: var(--on-dark); }\n.own-revolut .rv-phone-sub { font-size: 14px; color: var(--on-dark-mute); }\n.own-revolut .rv-phone-chart { width: 100%; height: 80px; margin-top: 12px; }\n.own-revolut .rv-phone-tags { display: flex; gap: 6px; flex-wrap: wrap; margin-top: 14px; }\n.own-revolut .rv-phone-tags span { padding: 5px 12px; border-radius: var(--r-full); background: color-mix(in srgb, var(--c) 22%, transparent); color: var(--c); font-size: 12px; font-weight: 600; }\n.own-revolut .rv-card-mock { width: 300px; aspect-ratio: 1.586 / 1; border-radius: var(--r-lg); padding: 22px; display: flex; flex-direction: column; justify-content: space-between; background: linear-gradient(135deg, #2b2f38, var(--accent-brown)); border: 1px solid var(--hairline-dark); }\n.own-revolut .rv-card-chip { width: 40px; height: 30px; border-radius: 6px; background: linear-gradient(135deg, #d9c08a, #a9855a); }\n.own-revolut .rv-card-num { font-family: var(--ui); font-size: 18px; letter-spacing: .24px; color: var(--on-dark); }\n.own-revolut .rv-card-name { font-size: 11px; font-weight: 600; letter-spacing: .18em; color: var(--on-dark-mute); }\n\n/* ── sub-nav pills ──────────────────────────────────────────────────────────── */\n.own-revolut .rv-subnav { display: flex; gap: 8px; padding: 28px var(--gut); overflow-x: auto; background: var(--canvas-dark); scrollbar-width: none; }\n.own-revolut .rv-subnav::-webkit-scrollbar { display: none; }\n.own-revolut .rv-pill { display: inline-flex; align-items: center; height: 36px; padding: 0 16px; border: 1px solid var(--hairline-dark); border-radius: var(--r-full); background: var(--surface-elevated); color: var(--on-dark); font-size: 14px; font-weight: 600; line-height: 1.43; white-space: nowrap; }\n.own-revolut .rv-pill:hover { background: #1c1e21; }\n\n/* ── bands ───────────────────────────────────────────────────────────────────── */\n.own-revolut .rv-band { padding: var(--section) var(--gut); }\n.own-revolut .rv-band-dark { background: var(--canvas-dark); color: var(--on-dark); }\n.own-revolut .rv-band-light { background: var(--canvas-light); color: var(--ink); }\n.own-revolut .rv-band-inner { max-width: 1200px; margin: 0 auto; }\n.own-revolut .rv-h2 { font-family: var(--display); font-size: clamp(36px, 5.4cqi, 80px); font-weight: 500; line-height: 1; letter-spacing: -.8px; color: var(--on-dark); }\n.own-revolut .rv-h2-dark { color: var(--ink); }\n.own-revolut .rv-band-sub { margin-top: 16px; max-width: 58ch; font-size: 18px; line-height: 1.56; letter-spacing: -.09px; }\n.own-revolut .rv-band-light .rv-band-sub { color: var(--charcoal); }\n.own-revolut .rv-band-dark .rv-band-sub { color: var(--on-dark-mute); }\n.own-revolut .rv-h3 { font-family: var(--display); font-size: 24px; font-weight: 500; line-height: 1.33; color: inherit; }\n\n/* ── mockup band ────────────────────────────────────────────────────────────── */\n.own-revolut .rv-mock-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 24px; margin-top: 40px; }\n.own-revolut .rv-mock { border-radius: var(--r-xl); padding: 32px; min-height: 300px; display: flex; flex-direction: column; justify-content: center; gap: 10px; }\n.own-revolut .rv-mock-phone { background: var(--surface-deep); align-items: center; }\n.own-revolut .rv-mock-screen { display: grid; gap: 12px; width: 100%; }\n.own-revolut .rv-mock-bar { display: block; height: 14px; border-radius: var(--r-full); background: color-mix(in srgb, var(--c) 30%, transparent); border-left: 3px solid var(--c); }\n.own-revolut .rv-mock-card { background: linear-gradient(135deg, #f4f4f4, #e2e2e7); color: var(--ink); }\n.own-revolut .rv-mock-tag { font-size: 13px; color: var(--mute); }\n.own-revolut .rv-mock-big { font-family: var(--display); font-size: 48px; font-weight: 500; line-height: 1.21; letter-spacing: -.48px; color: var(--accent-light-green); }\n.own-revolut .rv-mock-small { font-size: 14px; color: var(--mute); }\n.own-revolut .rv-mock-terminal { background: var(--surface-deep); justify-content: flex-start; padding-top: 44px; }\n.own-revolut .rv-mock-term-line { display: flex; align-items: center; gap: 10px; padding: 12px 0; border-bottom: 1px solid var(--hairline-dark); font-size: 15px; color: var(--on-dark); }\n.own-revolut .rv-mock-term-line span { display: grid; place-items: center; width: 24px; height: 24px; border-radius: var(--r-full); background: color-mix(in srgb, var(--c) 22%, transparent); color: var(--c); font-size: 13px; }\n\n/* ── feature cards ──────────────────────────────────────────────────────────── */\n.own-revolut .rv-feature-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 24px; margin-top: 40px; }\n.own-revolut .rv-fcard-dark { display: grid; gap: 12px; padding: 32px; border-radius: var(--r-lg); background: var(--surface-elevated); }\n.own-revolut .rv-fcard-dot { width: 44px; height: 44px; border-radius: var(--r-full); background: color-mix(in srgb, var(--c) 18%, transparent); border: 1px solid var(--c); }\n.own-revolut .rv-fcard-copy { font-size: 16px; line-height: 1.5; letter-spacing: .24px; color: var(--on-dark-mute); }\n\n/* ── plan grid ──────────────────────────────────────────────────────────────── */\n.own-revolut .rv-plan-grid { display: grid; grid-template-columns: repeat(4, 1fr); gap: 20px; margin-top: 40px; align-items: stretch; }\n.own-revolut .rv-plan-card { display: grid; gap: 12px; padding: 32px; border-radius: var(--r-lg); background: var(--surface-elevated); align-content: start; }\n.own-revolut .rv-plan-featured { background: var(--primary); color: var(--on-primary); }\n.own-revolut .rv-badge { justify-self: start; padding: 4px 12px; border-radius: var(--r-full); background: rgba(255, 255, 255, .1); color: var(--on-dark-mute); font-size: 13px; }\n.own-revolut .rv-plan-featured .rv-badge { background: rgba(255, 255, 255, .18); color: var(--on-primary); }\n.own-revolut .rv-badge-feature { background: var(--on-primary); color: var(--primary); font-weight: 600; }\n.own-revolut .rv-plan-name { font-family: var(--display); font-size: 32px; font-weight: 500; line-height: 1.19; letter-spacing: -.32px; }\n.own-revolut .rv-plan-price { font-family: var(--display); font-size: 40px; font-weight: 500; line-height: 1.2; letter-spacing: -.4px; }\n.own-revolut .rv-plan-price span { font-family: var(--ui); font-size: 14px; letter-spacing: 0; opacity: .7; }\n.own-revolut .rv-checks { list-style: none; display: grid; gap: 10px; margin: 4px 0 8px; font-size: 14px; color: inherit; opacity: .86; }\n.own-revolut .rv-checks li { padding-left: 24px; position: relative; }\n.own-revolut .rv-checks li::before { content: '\\2713'; position: absolute; left: 0; color: var(--accent-teal); }\n.own-revolut .rv-plan-featured .rv-checks li::before { color: var(--on-primary); }\n.own-revolut .rv-plan-card .rv-btn-outline-dark { border-color: var(--hairline-dark); }\n\n/* ── FAQ ─────────────────────────────────────────────────────────────────────── */\n.own-revolut .rv-faq { display: grid; gap: 0; margin-top: 34px; border-top: 1px solid var(--hairline-light); }\n.own-revolut .rv-faq-item { border-bottom: 1px solid var(--hairline-light); }\n.own-revolut .rv-faq-item summary { display: flex; align-items: center; justify-content: space-between; gap: 16px; padding: 24px 0; font-family: var(--display); font-size: 24px; font-weight: 500; line-height: 1.33; color: var(--ink); cursor: pointer; list-style: none; }\n.own-revolut .rv-faq-item summary::-webkit-details-marker { display: none; }\n.own-revolut .rv-faq-item summary::after { content: '+'; font-family: var(--ui); font-size: 24px; color: var(--mute); }\n.own-revolut .rv-faq-item[open] summary::after { content: '\\2212'; }\n.own-revolut .rv-faq-item p { padding-bottom: 24px; max-width: 72ch; font-size: 16px; line-height: 1.5; letter-spacing: .24px; color: var(--charcoal); }\n\n/* ── footer ─────────────────────────────────────────────────────────────────── */\n.own-revolut .rv-foot { background: var(--canvas-dark); color: var(--on-dark-mute); padding: 80px var(--gut) 28px; }\n.own-revolut .rv-foot-inner { display: grid; grid-template-columns: 1.4fr 1fr 1fr 1fr; gap: 32px; max-width: 1200px; margin: 0 auto; }\n.own-revolut .rv-foot-brand { display: inline-flex; align-items: center; gap: 9px; font-family: var(--display); font-size: 20px; font-weight: 500; color: var(--on-dark); }\n.own-revolut .rv-foot-cols { display: grid; gap: 10px; align-content: start; }\n.own-revolut .rv-foot-cols h3 { font-size: 14px; font-weight: 600; color: var(--on-dark); margin-bottom: 4px; }\n.own-revolut .rv-foot-cols a { font-size: 14px; color: var(--on-dark-mute); }\n.own-revolut .rv-foot-cols a:hover { color: var(--on-dark); }\n.own-revolut .rv-foot-legal { display: flex; align-items: center; justify-content: space-between; gap: 16px; flex-wrap: wrap; max-width: 1200px; margin: 40px auto 0; padding-top: 20px; border-top: 1px solid var(--divider-soft); font-size: 13px; }\n\n/* ── responsive ───────────────────────────────────────────────────────────── */\n@container frame (max-width: 1100px) {\n  .own-revolut .rv-menu { display: none; }\n  .own-revolut .rv-burger { display: flex; }\n  .own-revolut .rv-mock-grid { grid-template-columns: 1fr 1fr; }\n  .own-revolut .rv-feature-grid { grid-template-columns: 1fr 1fr; }\n  .own-revolut .rv-plan-grid { grid-template-columns: 1fr 1fr; }\n  .own-revolut .rv-foot-inner { grid-template-columns: 1fr 1fr 1fr; }\n}\n@container frame (max-width: 760px) {\n  .own-revolut .rv-link, .own-revolut .rv-icon { display: none; }\n  .own-revolut .rv-h1 { font-size: clamp(48px, 15cqi, 80px); letter-spacing: -1.2px; }\n  .own-revolut .rv-hero-mock { gap: 20px; }\n  .own-revolut .rv-mock-grid { grid-template-columns: 1fr; }\n  .own-revolut .rv-feature-grid { grid-template-columns: 1fr; }\n  .own-revolut .rv-plan-grid { grid-template-columns: 1fr; max-width: 440px; }\n  .own-revolut .rv-foot-inner { grid-template-columns: 1fr 1fr; }\n}\n@container frame (max-width: 430px) {\n  .own-revolut .rv-h1 { font-size: 48px; letter-spacing: -.6px; }\n  .own-revolut .rv-hero-sub { font-size: 16px; }\n  .own-revolut .rv-card-mock { width: 100%; max-width: 300px; }\n  .own-revolut .rv-foot-inner { grid-template-columns: 1fr; }\n}\n@media (prefers-reduced-motion: reduce) {\n  .own-revolut *, .own-revolut *::before, .own-revolut *::after { transition-duration: .001ms !important; animation-duration: .001ms !important; }\n}\n"};
/* ══ NORTHWIND — Revolut-language chrome for showcase.html ══════════════════
   Registers window.OWN_LAYOUTS['revolut'].init(root). Wires the FAQ accordion
   (single-open) and returns a cleanup that aborts every listener. */

(function () {
  var OWN = (window.OWN_LAYOUTS = window.OWN_LAYOUTS || {});

  OWN['revolut'] = {
    init: function (root) {
      var AC = window.AbortController ? new AbortController() : null;
      var signal = AC ? AC.signal : undefined;
      function on(el, type, fn, opt) { if (!el) return; opt = Object.assign({}, opt || {}); if (signal) opt.signal = signal; el.addEventListener(type, fn, opt); }

      on(root, 'click', function (e) {
        var s = e.target.closest ? e.target.closest('.rv-faq-item summary') : null;
        if (!s) return;
        var item = s.parentNode;
        if (!item.hasAttribute('open')) {
          Array.prototype.forEach.call(root.querySelectorAll('.rv-faq-item[open]'), function (d) {
            if (d !== item) d.removeAttribute('open');
          });
        }
      });

      return function cleanup() {
        if (AC) { try { AC.abort(); } catch (e) { /* ignore */ } }
      };
    }
  };
})();
